package br.com.conectatea.vinculo.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="tokens_vinculo")
public class TokenVinculo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="codigo_hash",nullable=false,unique=true,length=64) private String codigoHash; @Column(name="crianca_id",nullable=false) private Long criancaId; @Column(name="profissional_id",nullable=false) private Long profissionalId; @Enumerated(EnumType.STRING) @Column(nullable=false) private StatusToken status=StatusToken.PENDENTE; @Column(name="expira_em",nullable=false) private Instant expiraEm; @Column(name="usado_em") private Instant usadoEm; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Version private long version; protected TokenVinculo(){} public TokenVinculo(String h,Long c,Long p,Instant e){codigoHash=h;criancaId=c;profissionalId=p;expiraEm=e;} public Long getCriancaId(){return criancaId;} public Long getProfissionalId(){return profissionalId;} public StatusToken getStatus(){return status;} public Instant getExpiraEm(){return expiraEm;} public void consumir(){if(status!=StatusToken.PENDENTE||!expiraEm.isAfter(Instant.now()))throw new IllegalStateException("Token indisponível");status=StatusToken.USADO;usadoEm=Instant.now();} }
